using System.IO;
using System.Reflection;
using System.Windows.Media;

namespace SoleSurvivor.App;

/// <summary>
/// Sound effects and ambient loops. The WAVs are embedded in the exe (Sounds\*.wav, generated by
/// tools/sounds/gen_sounds.py) and extracted once to %LocalAppData%\SoleSurvivor\Sounds\&lt;version&gt;,
/// because WPF's MediaPlayer plays from a file or URL, not a stream. MediaPlayer is used (not SoundPlayer)
/// so several sounds can overlap. If anything about audio fails, the game carries on silently.
/// </summary>
internal static class Sound
{
    private const int Voices = 3;

    private static string _dir = "";
    private static readonly Dictionary<string, MediaPlayer[]> Pools = new();
    private static readonly Dictionary<string, int> NextVoice = new();
    private static MediaPlayer? _ambient;
    private static string? _ambientWanted;
    private static string? _ambientOpen;

    public static bool Available { get; private set; }
    public static bool Muted { get; private set; }
    /// <summary>Master volume, 0 to 1.</summary>
    public static double Volume { get; private set; } = 0.8;
    public static bool AmbientOn { get; private set; } = true;

    public static void Init(bool muted, double volume, bool ambientOn)
    {
        Muted = muted;
        Volume = Math.Clamp(volume, 0, 1);
        AmbientOn = ambientOn;
        try
        {
            var asm = Assembly.GetExecutingAssembly();
            string version = asm.GetName().Version?.ToString() ?? "0";
            _dir = Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData), "SoleSurvivor", "Sounds", version);
            Directory.CreateDirectory(_dir);
            foreach (string res in asm.GetManifestResourceNames())
            {
                if (!res.StartsWith("Sounds.", StringComparison.Ordinal) || !res.EndsWith(".wav", StringComparison.OrdinalIgnoreCase)) continue;
                string path = Path.Combine(_dir, res["Sounds.".Length..]);
                if (File.Exists(path)) continue;
                using var source = asm.GetManifestResourceStream(res);
                if (source is null) continue;
                string temp = path + ".tmp";
                using (var target = File.Create(temp)) source.CopyTo(target);
                File.Move(temp, path, overwrite: true);
            }
            Available = true;
        }
        catch (Exception)
        {
            Available = false;
        }
    }

    /// <summary>True if a sound of that name was shipped (and extracted).</summary>
    public static bool Has(string name) => Available && _dir.Length > 0 && File.Exists(Path.Combine(_dir, name + ".wav"));

    /// <summary>Play a one-shot effect by name (file name without .wav), at a relative volume.</summary>
    public static void Play(string name, double volume = 1.0)
    {
        if (!Available || Muted || Volume <= 0) return;
        try
        {
            if (!Pools.TryGetValue(name, out var pool))
            {
                string path = Path.Combine(_dir, name + ".wav");
                if (!File.Exists(path)) return;
                pool = new MediaPlayer[Voices];
                for (int i = 0; i < Voices; i++)
                {
                    pool[i] = new MediaPlayer();
                    pool[i].Open(new Uri(path, UriKind.Absolute));
                }
                Pools[name] = pool;
                NextVoice[name] = 0;
            }
            int v = NextVoice[name];
            NextVoice[name] = (v + 1) % Voices;
            var player = pool[v];
            player.Stop();
            player.Volume = Math.Clamp(Volume * volume, 0, 1);
            player.Position = TimeSpan.Zero;
            player.Play();
        }
        catch (Exception)
        {
            // Audio is a nicety; never let it break the game.
        }
    }

    /// <summary>Play a short burst of footsteps, spread over <paramref name="ms"/>.</summary>
    public static async Task StepsAsync(double ms, int count = 3)
    {
        for (int i = 0; i < count; i++)
        {
            Play("step", 0.8);
            await Task.Delay(TimeSpan.FromMilliseconds(Math.Max(60, ms / count)));
        }
    }

    /// <summary>Choose the background loop for a scenario (amb_&lt;id&gt;.wav), or null for silence.</summary>
    public static void SetAmbient(string? scenarioId)
    {
        _ambientWanted = scenarioId is null ? null : "amb_" + scenarioId;
        RefreshAmbient();
    }

    public static void SetMuted(bool muted)
    {
        Muted = muted;
        if (muted)
            foreach (var pool in Pools.Values)
                foreach (var p in pool)
                    p.Stop();
        RefreshAmbient();
    }

    public static void SetVolume(double volume)
    {
        Volume = Math.Clamp(volume, 0, 1);
        RefreshAmbient();
    }

    public static void SetAmbientOn(bool on)
    {
        AmbientOn = on;
        RefreshAmbient();
    }

    private static void RefreshAmbient()
    {
        if (!Available) return;
        try
        {
            if (_ambient is null)
            {
                var player = new MediaPlayer();
                player.MediaEnded += (_, _) =>
                {
                    player.Position = TimeSpan.Zero;   // loop
                    player.Play();
                };
                _ambient = player;
            }
            if (Muted || !AmbientOn || _ambientWanted is null || Volume <= 0)
            {
                _ambient.Pause();
                return;
            }
            if (_ambientOpen != _ambientWanted)
            {
                string path = Path.Combine(_dir, _ambientWanted + ".wav");
                if (!File.Exists(path))
                {
                    _ambient.Stop();
                    return;
                }
                _ambient.Open(new Uri(path, UriKind.Absolute));
                _ambientOpen = _ambientWanted;
            }
            _ambient.Volume = Math.Clamp(Volume * 0.55, 0, 1);
            _ambient.Play();
        }
        catch (Exception)
        {
            // Ignore: ambience is optional.
        }
    }
}
